  "steps": [
    {
      "id": 1,
      "claim": "Radio waves are electromagnetic radiation that lie outside the visible spectrum, so they are not visible to the human eye.",
      "evidence": "The visible spectrum spans wavelengths ~400–700 nm; radio wavelengths are >1 mm, far longer than visible light.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Radio waves used for tracking have relatively low frequencies compared to many other parts of the electromagnetic spectrum.",
      "evidence": "Common tracking bands are in the VHF/UHF range (30 MHz–3 GHz), lower than infrared, visible, ultraviolet, etc.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The collar, not the animal, contains an electronic transmitter that deliberately generates the radio signal.",
      "evidence": "Telemetry collars are equipped with batteries and RF transmitters designed to emit a coded radio pulse.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "An omnidirectional antenna on the collar radiates the signal outward in (approximately) all directions.",
      "evidence": "A simple dipole or monopole antenna radiates a pattern that covers 360° in the horizontal plane; this is standard in wildlife telemetry.",
      "weight": 0.40,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Because the signal spreads in all directions, a receiver can detect it from many positions without needing a specific orientation or line‑of‑sight, enabling effective tracking of a moving animal.",
      "evidence": "Field biologists locate collars by triangulating signal strength from multiple receiver locations; omnidirectional emission makes this possible.",
      "weight": 0.20,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Step 2 is a weak justification: the low frequency of radio waves is not the primary reason they are chosen for tracking; tracking can be performed at higher frequencies as well, so frequency alone does not explain the method’s usefulness.",
      "evidence": "Telemetry systems exist at VHF (~150 MHz) and UHF (~400 MHz); some use higher frequencies (e.g., GPS at 1.5 GHz) and still function for tracking, showing frequency is not decisive.",
      "weight": 0.05,
      "depends_on": [2]
    }
  ],
  "answer": "C",
  "confidence": 0.98,
